// Fields the app renders as string arrays (see lib/avatar-chat.ts asStringList).
// The model often returns these as prose, so coerce rather than reject.
const LIST_KEYS = new Set([
  'objections', 'headlines', 'social_hooks', 'email_subject_lines',
  'primary_goals', 'values_and_beliefs', 'trusted_influences',
  'content_ideas', 'search_topics', 'conversation_starters'
]);

function toList(value) {
  if (Array.isArray(value)) {
    return value.map((item) => String(item ?? '').trim()).filter(Boolean);
  }
  if (typeof value === 'string') {
    return value.split(/\r?\n|[;•]|,(?=\s)/).map((part) => part.trim()).filter(Boolean);
  }
  return [];
}

function mergeBlueprint(previous, incoming) {
  if (!incoming || typeof incoming !== 'object') return previous ?? {};
  const next = { ...(previous ?? {}) };
  for (const [key, value] of Object.entries(incoming)) {
    if (LIST_KEYS.has(key)) {
      const list = toList(value);
      if (list.length) next[key] = list;
    } else if (typeof value === 'string' && value.trim()) {
      next[key] = value.trim();
    }
  }
  next.generated_at = new Date().toISOString();
  return next;
}

const source = $input.first().json;
const raw = source.output ?? source.text ?? source.response?.text ?? source;
let generated = raw;
if (typeof raw === 'string') {
  try {
    generated = JSON.parse(raw.trim().replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim());
  } catch {
    generated = { reply: raw, update_blueprint: false };
  }
}
if (generated?.output) generated = generated.output;

const input = $('Merge Session History').first().json;
const previous = input.blueprint ?? {};
const reply = typeof generated?.reply === 'string' && generated.reply.trim()
  ? generated.reply.trim()
  : (typeof raw === 'string' && raw.trim() ? raw.trim() : '');
if (!reply) {
  throw new Error('Avatar IQ agent returned an empty reply.');
}
const shouldUpdate = generated?.update_blueprint === true || Boolean(generated?.blueprint?.persona_name);
const blueprint = shouldUpdate ? mergeBlueprint(previous, generated?.blueprint) : previous;

return [{
  json: {
    reply,
    blueprint,
    has_blueprint: Boolean(blueprint?.persona_name),
    session_id: input.session_id,
    user_id: input.user_id
  }
}];

const headers = $json.headers ?? {};
const raw = headers.authorization ?? headers.Authorization ?? '';
const token = String(raw).replace(/^Bearer\s+/i, '').trim();
if (!token || token.length > 8192) {
  throw new Error('Missing Firebase ID token in the Authorization header.');
}
return [{ json: { id_token: token } }];

const input = $('Verify User and Normalize').first().json;
const ownedBy = (doc) => (doc && (!doc.owner_id || doc.owner_id === input.user_id) ? doc : {});

const memory = ownedBy($('Load Account Memory').first()?.json);
const stored = ownedBy($input.first()?.json);

// Per-user prompt layers, written in the background by the profile builder.
// Treated as DATA downstream, never as instructions.
const layers = memory.prompt_layers && typeof memory.prompt_layers === 'object' ? memory.prompt_layers : {};

const normalize = (item) => ({
  role: item?.role === 'assistant' ? 'assistant' : 'user',
  text: String(item?.text ?? '').slice(0, 8000)
});

const storedMessages = Array.isArray(stored.messages) ? stored.messages : [];
const history = (storedMessages.length ? storedMessages : input.messages)
  .map(normalize)
  .filter((item) => item.text)
  .slice(-24);

return [{
  json: {
    ...input,
    history,
    chat_style: String(layers.chat_style ?? '').slice(0, 2000),
    business_profile: memory.business_profile ?? {},
    memory_summary: String(memory.memory_summary ?? '').slice(0, 1000)
  }
}];

const result = $input.first().json;
const input = $('Merge Session History').first().json;
const now = new Date().toISOString();

const history = [...input.history];
const last = history[history.length - 1];
if (input.message && !(last?.role === 'user' && last?.text === input.message)) {
  history.push({ role: 'user', text: input.message });
}
history.push({ role: 'assistant', text: result.reply });

const messages = history.slice(-60).map((item, index) => ({
  id: `${result.session_id}-${index}`,
  role: item.role,
  text: item.text,
  created_at: now
}));

return [{
  json: {
    session_id: result.session_id,
    owner_id: result.user_id,
    workflow: 'avatar-iq',
    messages,
    status: result.has_blueprint ? 'completed' : 'draft',
    step: result.has_blueprint ? 4 : 1,
    blueprint: result.blueprint ?? {},
    onboarding_complete: Boolean(result.has_blueprint),
    business_profile: { business: input.message },
    audience_profile: result.blueprint ?? {},
    memory_summary: result.blueprint?.persona_name ? `Ideal buyer: ${result.blueprint.persona_name}` : '',
    source_session_id: result.session_id,
    updated_at: now
  }
}];

// Reached when the agent or the validator fails. A bad generation must never
// cost the user their turn: answer with something usable, keep the blueprint
// they already had, and let them continue the conversation.
let input = {};
try {
  input = $('Merge Session History').first().json ?? {};
} catch {
  try { input = $('Verify User and Normalize').first().json ?? {}; } catch { input = {}; }
}

const failure = $input.first()?.json ?? {};
const detail = String(failure.error?.message ?? failure.message ?? '').slice(0, 300);
console.log('Webinar Chat recovered from a failed turn:', detail);

const previous = input.blueprint ?? {};

return [{
  json: {
    reply: "Sorry — I lost that one on my side. Say it again, or put it a different way, and I'll pick it straight back up.",
    blueprint: previous,
    has_blueprint: Boolean(previous?.persona_name),
    session_id: input.session_id ?? null,
    user_id: input.user_id ?? null,
    recovered: true
  }
}];
